import * as React from 'react';
import { CardContent, Grid, IconButton, Tooltip, Fab } from '@mui/material';
// project imports
import MainCard from 'ui-component/cards/MainCard';
import { useDispatch, useSelector } from 'store';

import { getInquriesList } from 'store/slices/inquries';

// assetss
import EditIcon from '@mui/icons-material/Edit';
import PrintIcon from '@mui/icons-material/PrintTwoTone';
import AddIcon from '@mui/icons-material/AddTwoTone';
import DynamicTable from 'views/commons/tables/DynamicTable';
import DeleteIcon from '@mui/icons-material/Delete';
import DeleteAlert from 'views/commons/alerts/deleteAlarts';
import useSnackbar from 'hooks/useSnackbar';
import GenericModelForm from 'views/commons/modelform/GenericModleForm';
import ApiRequest from 'utils/apiService';
import RenderDetails from './RenderDetails';
import useAuth from 'hooks/useAuth';
import GenericSearchFilter from 'views/commons/search/GenericSearchFilter';
import FilterListIcon from '@mui/icons-material/FilterList';
import { USER_QUERY_FIELDS, SEARCH_FIELDS, USER_QUERY_TABLE_FIELDS } from 'store/constant';
import useTableManagement from 'hooks/useTableManagement';
import { useTheme } from '@mui/styles';

const UserQueriesView = () => {
    const theme = useTheme();
    const { user } = useAuth();
    const dispatch = useDispatch();
    const { entities } = useSelector((state) => state.inquires);
    const inquires = entities.inquires || [];

    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState([]);
    const { showSnackbar } = useSnackbar();

    const [open, setOpen] = React.useState(false);

    const [editData, setEditData] = React.useState(null);
    const [initialImages, setInitialImages] = React.useState([]);
    const [removedImages, setRemovedImages] = React.useState([]);
    const [searchParams, setSearchParams] = React.useState({}); // ✅ Stores search filter params
    const [filterOpen, setFilterOpen] = React.useState(false);
    const {
        rowsPerPage,
        page,
        totalRecords, // ✅ Get total from Redux
        orderBy,
        order,
        handlePageChange,
        handleRowsPerPageChange,
        handleSortChange,
        handleSearch,
        handleFilters,
        handleSelectAll,
        handleRowClick,
        selected,
        setSelected,
        loading,
        fetchData,
        setLoading
    } = useTableManagement({ fetchFunction: getInquriesList });

    const handleEdit = (row) => {
        setEditData(row); // ✅ Store the selected row data
        setOpen(true); // ✅ Open modal

        if (row.images && row.images.length > 0) {
            // ✅ Ensure full URL is set for images
            const formattedImages = row.images.map((img) => ({
                ...img,
                image_url: `https://13.53.197.110:3001/${img.image_url}` // 🔹 Ensure correct full URL
            }));

            setInitialImages(formattedImages); // ✅ Store images in correct format
        } else {
            setInitialImages([]); // ✅ Reset images if none
        }

        setRemovedImages([]); // ✅ Reset removed images
    };

    const handleDelete = (selectedIds) => {
        if (selectedIds.length === 0) return;
        setSelectedIds(selectedIds);
        setDeleteDialogOpen(true);
    };

    const handleClickOpenDialog = () => {
        setOpen(true);
    };

    const handleCloseDialog = () => {
        setOpen(false);
        setEditData(null);
    };

    const handlePermissionSubmit = async (data, resetForm) => {
        setLoading(true);

        const url = editData ? `/inquires/edit/${editData.id}` : `/inquires/post`;
        const method = editData ? 'PATCH' : 'POST';
        const defaultMessage = editData ? 'Inquiry Updated successfully!' : 'Inquiry Added successfully!';

        const formData = new FormData();

        Object.keys(data).forEach((key) => {
            if (key !== 'images' && key !== 'removed_images' && data[key] !== undefined) {
                formData.append(key, data[key]);
            }
        });

        if (user?.id) {
            formData.append('user_id', user.id);
        }

        // ✅ Append removed images as JSON string
        formData.append('removed_images', JSON.stringify(removedImages));

        // ✅ Handle images correctly
        const allImages = [...(data.images || [])];

        allImages.forEach((image, index) => {
            if (image instanceof File) {
                formData.append('images', image); // ✅ Only add new images
            }
        });

        try {
            const response = await ApiRequest(
                method,
                url,
                formData,
                {},
                {
                    'Content-Type': 'multipart/form-data'
                }
            );

            showSnackbar(response.message || defaultMessage, 'success');

            dispatch(getInquriesList({ limit: rowsPerPage, page, ...searchParams, sortBy: orderBy, order }));

            resetForm();
            setRemovedImages([]); // ✅ Clear removed images after submission
        } catch (error) {
            showSnackbar(error.message, 'error');
        } finally {
            setLoading(false);
            setOpen(false);
            setEditData(null);
        }
    };

    return (
        <MainCard content={false} sx={{ background: theme.palette.text.primary }}>
            <CardContent>
                <Grid container justifyContent="space-between" alignItems="right" spacing={2}>
                    <Grid item xs={12} sm={12} sx={{ textAlign: 'right' }}>
                        <Tooltip title="Print">
                            <IconButton size="large">
                                <PrintIcon />
                            </IconButton>
                        </Tooltip>
                        <Tooltip title="Filter">
                            <IconButton size="large" onClick={() => setFilterOpen(!filterOpen)}>
                                <FilterListIcon />
                            </IconButton>
                        </Tooltip>
                        {/* product add & dialog */}
                        <Tooltip title="Add Query">
                            <Fab
                                color="primary"
                                size="small"
                                onClick={handleClickOpenDialog}
                                sx={{ boxShadow: 'none', ml: 1, width: 32, height: 32, minHeight: 32 }}
                            >
                                <AddIcon fontSize="small" />
                            </Fab>
                        </Tooltip>
                        <GenericModelForm
                            open={open}
                            handleCloseDialog={handleCloseDialog}
                            position="center"
                            fields={USER_QUERY_FIELDS}
                            onSubmit={handlePermissionSubmit}
                            formLabel={editData ? 'Edit Query' : 'Add Query'}
                            editData={editData}
                            initialImages={initialImages} // ✅ Pass initial images
                            setInitialImages={setInitialImages} // ✅ Pass setter function
                            removedImages={removedImages} // ✅ Pass removed images array
                            setRemovedImages={setRemovedImages} // ✅ Pass setter function
                        />
                    </Grid>
                </Grid>
                <Grid container justifyContent="space-between" alignItems="center" spacing={2}>
                    <Grid item xs={12} sm={12}>
                        <GenericSearchFilter
                            fields={SEARCH_FIELDS}
                            onSearch={(values) => {
                                setSearchParams(values); // ✅ Update search state
                                handleFilters(values); // ✅ Trigger API with new search values
                            }}
                            onFilter={handleFilters}
                            searchValues={searchParams} // ✅ Use `searchParams`
                            setSearchValues={setSearchParams} // ✅ Use `setSearchParams`
                            searchMode="manual"
                            expanded={filterOpen}
                            setExpanded={setFilterOpen}
                            loading={loading}
                        />
                    </Grid>
                </Grid>
            </CardContent>
            <DynamicTable
                columns={USER_QUERY_TABLE_FIELDS}
                data={inquires}
                total={totalRecords}
                page={page}
                rowsPerPage={rowsPerPage}
                onPageChange={handlePageChange}
                onRowsPerPageChange={handleRowsPerPageChange}
                order={order}
                orderBy={orderBy}
                onRequestSort={handleSortChange}
                selected={selected || []}
                onSelectAllClick={handleSelectAll} // ✅ Pass select all function
                onRowClick={handleRowClick} // ✅ Pass row selection function
                onDelete={handleDelete} // ✅ Pass delete function
                showCheckbox // ✅ Add this to show checkboxes
                collapsible={false}
                customtheme="light"
                renderDetails={(row) => <RenderDetails row={row} />}
                renderActions={(row) => (
                    <>
                        <IconButton size="small" onClick={() => handleEdit(row)}>
                            <EditIcon />
                        </IconButton>
                        <IconButton disabled={selected.length > 0} size="small" onClick={() => handleDelete([row.id])}>
                            <DeleteIcon />
                        </IconButton>
                    </>
                )}
                loading={loading}
                customize
            />

            <DeleteAlert
                open={deleteDialogOpen}
                onClose={() => setDeleteDialogOpen(false)}
                selectedIds={selectedIds}
                endpoint="/inquires/delete"
                onDeleteSuccess={() => {
                    showSnackbar('User deleted successfully!', 'success');
                    fetchData({}, () => {
                        setDeleteDialogOpen(false);
                        setSelected([]);
                        setSelectedIds([]); // ✅ Clear selection after delete
                    });
                }}
                message="Are you sure you want to delete the selected permissions?"
            />
        </MainCard>
    );
};

export default UserQueriesView;
