import { useState } from 'react';
import PropTypes from 'prop-types';
import {
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TableSortLabel,
    TablePagination,
    Checkbox,
    Toolbar,
    Tooltip,
    IconButton,
    CircularProgress,
    Typography,
    Collapse,
    Box,
    Chip
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import { visuallyHidden } from '@mui/utils';
import { styled, useTheme } from '@mui/material/styles';
import formatDate from 'utils/dateUtils';

// ✅ Styled Components with Custom Styles
const StyledTableCell = styled(TableCell)(({ theme, customtheme, customize, isHeader }) => ({
    backgroundColor: 'inherit',
    color: theme.palette.primary.dark,
    fontWeight: customize ? 'bold' : 'normal',
    ...(isHeader && {
        backgroundColor: theme.palette.primary.dark, // Dark background for header cells
        color: theme.palette.common.white, // White text for header cells
        textTransform: 'uppercase',
        fontWeight: 600, // Bold text for header cells
        fontSize: '0.875rem', // Larger font size for header cells
        '& .MuiTableSortLabel-root': {
            color: theme.palette.common.white, // Ensure the sort label text is white
            '&:hover': {
                color: theme.palette.common.white // Ensure the sort label text stays white on hover
            }
        }
    })
}));

const StyledTableRow = styled(TableRow)(({ theme, customtheme, customize, index }) => ({
    backgroundColor: customize ? theme.palette.text.primary : theme.palette.text.primary,
    '&:nth-of-type(odd)': {
        backgroundColor: customize ? theme.palette.secondary.light : theme.palette.secondary.light
    },
    '&:last-of-type td, &:last-of-type th': {
        border: 0
    },
    fontSize: '0.875rem', // Use a smaller, more readable font size (14px)
    fontWeight: 600, // Use a normal font weight for better readability
    lineHeight: 1.5, // Add line height for better spacing
    '&:hover': {
        backgroundColor: theme.palette.action.hover, // Add a hover effect for better interactivity
        cursor: 'pointer' // Change cursor to pointer on hover
    }
}));

// ✅ Utility Functions
const getNestedValue = (obj, path) => {
    if (!path) return '';
    return path.split('.').reduce((acc, part) => {
        if (acc === null || acc === undefined) return '';
        return acc[part];
    }, obj);
};

const getCellContent = (column, row) => {
    if (!row || !column) return '';

    // Get value using nested property access
    const value = getNestedValue(row, column.id);

    // Handle date formatting
    if (['createdAt', 'updatedAt', 'deletedAt'].includes(column.id)) {
        return formatDate(value, 'short');
    }

    // Handle status with custom labels
    if (column.id === 'status') {
        const labelMap = {
            true: column.statusLabels?.true || 'Active',
            false: column.statusLabels?.false || 'Banned',
            active: column.statusLabels?.active || 'Active',
            inactive: column.statusLabels?.inactive || 'Inactive',
            pending: column.statusLabels?.pending || 'Pending'
        };

        const statusValue = String(value).toLowerCase();
        const label = labelMap[statusValue] || labelMap[String(value)] || 'Unknown';

        if (statusValue === 'true' || statusValue === 'active') {
            return <Chip label={label} size="small" color="success" />;
        }
        if (statusValue === 'false' || statusValue === 'inactive') {
            return <Chip label={label} size="small" color="error" />;
        }
        return <Chip label={label} size="small" color="default" />;
    }

    // Handle verified statuses with custom labels
    const verifiedHandlers = {
        email_verified: {
            true: column.emailVerifiedLabels?.true || 'Email Verified',
            false: column.emailVerifiedLabels?.false || 'Email Not Verified'
        },
        mobile_verified: {
            true: column.mobileVerifiedLabels?.true || 'Mobile Verified',
            false: column.mobileVerifiedLabels?.false || 'Mobile Not Verified'
        }
    };

    if (verifiedHandlers[column.id]) {
        const labelMap = verifiedHandlers[column.id];
        const boolValue = Boolean(value);
        const label = labelMap[boolValue] || 'Unknown';

        return boolValue ? <Chip label={label} size="small" color="success" /> : <Chip label={label} size="small" color="error" />;
    }

    return value ?? '';
};
// ✅ Row Component (Handles Collapsible Rows & Custom Styles)
const Row = ({
    row,
    columns,
    renderActions,
    showActions = true,
    collapsible,
    showCheckbox,
    onRowClick,
    selected,
    customtheme,
    customize,
    index,
    renderDetails
}) => {
    const [open, setOpen] = useState(false);
    const isSelected = selected.includes(row?.id);

    return (
        <>
            <StyledTableRow customtheme={customtheme} customize={customize} index={index}>
                {showCheckbox && (
                    <StyledTableCell padding="checkbox">
                        <Checkbox color="primary" checked={isSelected} onClick={(event) => onRowClick(event, row.id)} />
                    </StyledTableCell>
                )}

                {collapsible && (
                    <StyledTableCell padding="checkbox">
                        <IconButton size="small" onClick={() => setOpen(!open)}>
                            {open ? <KeyboardArrowUpIcon /> : <KeyboardArrowDownIcon />}
                        </IconButton>
                    </StyledTableCell>
                )}

                {columns.map((column) => (
                    <StyledTableCell key={column.id} align={column.align} customize={customize}>
                        {getCellContent(column, row)}
                    </StyledTableCell>
                ))}

                {showActions && renderActions && (
                    <StyledTableCell align="center" customize={customize}>
                        {renderActions(row)}
                    </StyledTableCell>
                )}
            </StyledTableRow>

            {collapsible && renderDetails && (
                <TableRow>
                    <TableCell colSpan={columns.length + (showCheckbox ? 2 : 1)}>
                        <Collapse in={open} timeout="auto" unmountOnExit>
                            <Box sx={{ margin: 1 }}>{typeof renderDetails === 'function' ? renderDetails(row) : renderDetails}</Box>
                        </Collapse>
                    </TableCell>
                </TableRow>
            )}
        </>
    );
};

// ✅ Main Table Component
const DynamicTable = ({
    columns = [],
    data = [],
    total = 0,
    page = 0,
    rowsPerPage = 5,
    onPageChange,
    onRowsPerPageChange,
    order,
    orderBy,
    onRequestSort,
    renderActions,
    showActions = true,
    loading,
    collapsible = false,
    selected = [],
    onSelectAllClick,
    onRowClick,
    onDelete,
    showCheckbox = true,
    customtheme = 'light',
    customize = false,
    renderDetails
}) => {
    const theme = useTheme();

    if (loading) {
        return (
            <TableContainer>
                <Table>
                    <TableBody>
                        <TableRow>
                            <TableCell colSpan={columns.length + (showCheckbox ? 3 : 2)} align="center">
                                <CircularProgress />
                            </TableCell>
                        </TableRow>
                    </TableBody>
                </Table>
            </TableContainer>
        );
    }

    if (data.length === 0) {
        return (
            <TableContainer>
                <Table>
                    <TableBody>
                        <TableRow>
                            <TableCell colSpan={columns.length + (showCheckbox ? 3 : 2)} align="center">
                                <Typography variant="h6" color="textSecondary">
                                    No Data Found
                                </Typography>
                            </TableCell>
                        </TableRow>
                    </TableBody>
                </Table>
            </TableContainer>
        );
    }

    return (
        <>
            <Toolbar>
                {selected.length > 0 && (
                    <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
                        {`${selected.length} selected`}
                    </Typography>
                )}
                {selected.length > 0 && (
                    <Tooltip title="Delete">
                        <IconButton onClick={() => onDelete(selected)} color="error">
                            <DeleteIcon />
                        </IconButton>
                    </Tooltip>
                )}
            </Toolbar>

            <TableContainer>
                <Table>
                    <TableHead sx={{ background: '#01586A' }}>
                        <TableRow>
                            {showCheckbox && (
                                <StyledTableCell padding="checkbox" customize={customize} isHeader>
                                    <Checkbox
                                        color="primary"
                                        indeterminate={selected.length > 0 && selected.length < data.length}
                                        checked={data.length > 0 && selected.length === data.length}
                                        onChange={(e) => onSelectAllClick(e, data || [])}
                                    />
                                </StyledTableCell>
                            )}

                            {/* ✅ Empty Cell to Align Header When Collapsible */}
                            {collapsible && <StyledTableCell padding="checkbox" customize={customize} />}

                            {columns.map((column) => (
                                <StyledTableCell
                                    key={column.id}
                                    align={column.align}
                                    customtheme={customtheme}
                                    customize={customize}
                                    isHeader
                                >
                                    <TableSortLabel
                                        active={orderBy === column.id}
                                        direction={order}
                                        onClick={() => onRequestSort(column.id)}
                                        backgroundColor="red"
                                    >
                                        {column.label}
                                        {orderBy === column.id && (
                                            <span style={visuallyHidden}>
                                                {order === 'desc' ? 'sorted descending' : 'sorted ascending'}
                                            </span>
                                        )}
                                    </TableSortLabel>
                                </StyledTableCell>
                            ))}
                            {showActions && renderActions && (
                                <StyledTableCell align="center" customize={customize} isHeader style={{ color: 'white' }}>
                                    Actions
                                </StyledTableCell>
                            )}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {data.map((row, index) => (
                            <Row
                                key={row?.id}
                                row={row}
                                columns={columns}
                                renderActions={renderActions}
                                showActions={showActions}
                                collapsible={collapsible}
                                showCheckbox={showCheckbox}
                                onRowClick={onRowClick}
                                selected={selected}
                                customtheme={customtheme}
                                customize={customize}
                                index={index}
                                renderDetails={renderDetails}
                            />
                        ))}
                    </TableBody>
                </Table>
            </TableContainer>

            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={total}
                rowsPerPage={rowsPerPage}
                page={page}
                onPageChange={onPageChange}
                onRowsPerPageChange={onRowsPerPageChange}
                sx={{
                    color: theme.palette.primary.dark,
                    '& .MuiTablePagination-displayedRows': {
                        color: theme.palette.primary.dark
                    },
                    '& .MuiTablePagination-selectLabel': {
                        // 👈 Target the "Rows per page" label
                        color: theme.palette.primary.dark, // Change to your desired color
                        fontSize: '0.875rem' // Optional: Adjust font size
                    }
                }}
            />
        </>
    );
};

export default DynamicTable;
